const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=n=>Number.isFinite(n)?n.toLocaleString('ko-KR',{maximumFractionDigits:2}):'—';
const pct=n=>Number.isFinite(n)?`${n>0?'+':''}${number(n)}%`:'—';
const stamp=(s,z='Asia/Seoul')=>s?new Intl.DateTimeFormat('ko-KR',{timeZone:z,dateStyle:'short',timeStyle:'short'}).format(new Date(s)):'미확인';
const roles={manufacture:'제조',design:'설계',equipment:'장비 공급',material:'소재',distribution:'유통',platform:'플랫폼·서비스'};
const markets={datacenter:'데이터센터·서버',mobile:'모바일',pc:'PC·컴퓨팅',automotive:'자동차',industrial:'산업용',enterprise:'기업 IT',consumer:'소비자 기기'};
const customers={oem:'기기 제조업체(OEM)',cloud:'클라우드 사업자',enterprise:'기업 고객',consumer:'일반 소비자'};
export function mountCompetitors(root,{navigate}={}){
 let data=null,ticker='',mode='competitors',pairTicker='',productId='',busy=false,request=0,searchTimer,searchController;
 async function load(t=ticker){const id=++request;busy=true;render();try{const r=await fetch('/api/competitors'+(t?'?ticker='+encodeURIComponent(t):''));const d=await r.json();if(id!==request)return;data=d;ticker=t;}catch{if(id===request)data={status:'error',message:'저장된 경쟁사 결과를 불러오지 못했습니다.',items:[]};}finally{if(id===request){busy=false;render();}}}
 async function select(t){pairTicker='';mode='competitors';ticker=t;try{await fetch('/api/competitors',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ticker:t})});}catch{}await load(t);}
 const list=()=>data?.selected?.[mode]||[];
 function profileColumn(p,side,match){const product=match?.[side];return `<div class="competitor-profile"><h4><a href="/stock/${p.market}/${encodeURIComponent(p.ticker)}?tab=company">${esc(p.marketName||p.name)} · ${esc(p.ticker)} ↗</a></h4><dl><dt>제품·서비스</dt><dd>${esc(product?.name||p.products.map(x=>x.name).join(' · ')||'공시 추출 대기')}</dd><dt>용도 확인 표현</dt><dd>${esc(product?.useTerms?.join(' · ')||'미확인')}</dd><dt>가치사슬 역할</dt><dd>${esc(product?.roles.map(r=>roles[r]||r).join(' · ')||'미확인')}</dd><dt>고객 유형</dt><dd>${esc(product?.customers.map(c=>customers[c]||c).join(' · ')||'미확인')}</dd><dt>최종 사용 시장</dt><dd>${esc(product?.markets.map(m=>markets[m]||m).join(' · ')||'미확인')}</dd><dt>해당 제품 매출 비중</dt><dd>${Number.isFinite(product?.revenueShare)?number(product.revenueShare)+'%':'미공개·미추출 · 추정하지 않음'}</dd></dl><p class="us-kr-note">${esc(p.source)} · 공시 ${esc(p.sourceDate)}<br>확인 ${esc(stamp(p.lastVerifiedAt||p.checkedAt))} KST</p><a href="${esc(p.sourceUrl)}" target="_blank" rel="noopener noreferrer">공시 원문 ↗</a>${product?`<details><summary>제품·역할·고객 시장 근거 문장</summary>${[...product.evidence.ownership,...product.evidence.market].map(e=>`<blockquote>${esc(e.text)}<small>${esc(e.locator)}</small></blockquote>`).join('')}</details>`:''}</div>`;}
 function render(){
  const s=data?.session,selected=data?.selected,items=list(),comparison=items.find(p=>p.krTicker===pairTicker),match=comparison?.matches?.find(m=>m.product===productId)||comparison?.matches?.[0]||(comparison?.supply?.[0]?{us:selected.profile.products.find(p=>p.id===comparison.supply[0].usProduct),kr:comparison.kr.products.find(p=>p.id===comparison.supply[0].krProduct)}:null);
  root.innerHTML=`<div class="panel-heading"><div><div class="eyebrow">COMPANY → COMPETITOR</div><h2>어젯밤 오른 미국 기업 → 국내 경쟁사</h2></div><button data-competitor-refresh ${busy?'disabled':''}>${busy?'확인 중':'새로고침'}</button></div><div class="us-kr-body"><form class="competitor-search"><label for="competitor-query">미국 기업 직접 찾기</label><input id="competitor-query" autocomplete="off" placeholder="기업명 또는 티커 · 예: MU, NVIDIA" aria-controls="competitor-search-results"><div id="competitor-search-results" aria-live="polite"></div></form>${data?.message?`<p role="status">${esc(data.message)}</p>`:''}${s?`<p class="us-kr-dates">미국 정규장 <b>${esc(s.usDate)}</b> → 다음 국내 거래일 <b>${esc(s.krDate)}</b>${data.stale?' · 갱신 지연 · 저장 자료':''}</p><p class="us-kr-note">마감 ${esc(stamp(s.closeAt,'America/New_York'))} ET / ${esc(stamp(s.closeAt))} KST · 수집 ${esc(stamp(s.observedAt))} KST<br>시가총액 ${number(data.thresholds.minMarketCap/1e9)}십억 USD 이상 · 가격×거래량 ${number(data.thresholds.minDollarVolume/1e6)}백만 USD 이상 · 상승률은 경쟁 점수에 미포함</p>`:''}<div class="us-kr-industries competitor-risers" aria-label="상승한 미국 개별 기업">${(data?.items||[]).map(x=>`<button data-competitor-select="${esc(x.ticker)}" aria-pressed="${ticker===x.ticker}"><strong>${esc(x.name)}</strong><span>${esc(x.ticker)}</span><b>${pct(x.changePct)}</b><small>${esc(s?.usDate)} 정규장</small></button>`).join('')||'<p class="us-kr-note">조건을 충족한 정규장 상승 종목을 확인하고 있습니다.</p>'}</div>${selected?`<section class="competitor-selected"><h3>${esc(selected.name)} <small>${esc(selected.ticker)}</small> ${selected.quote?`<span>${pct(selected.quote.changePct)}</span>`:''}</h3><p class="us-kr-note">${selected.quote?'미국 정규장 '+esc(s.usDate):'현재 저장된 정규장 분석 대상 밖 · 상승률 미표시'}</p><p>${esc(selected.cause.message)}</p>${selected.cause.events.map(e=>`<p><a href="${esc(e.source_url)}" target="_blank" rel="noopener noreferrer">${esc(e.title_ko)}</a> · ${esc(e.filed_date)}<br><small>${esc(e.label)}</small></p>`).join('')}<a href="/stock/US/${encodeURIComponent(ticker)}?tab=company">미국 종목 상세 ↗</a>${selected.message?`<p role="status">${esc(selected.message)}</p>`:''}<div class="competitor-tabs" role="tablist" aria-label="사업 관계"><button role="tab" aria-selected="${mode==='competitors'}" data-competitor-mode="competitors">국내 경쟁사 ${selected.competitors.length}</button><button role="tab" aria-selected="${mode==='supply'}" data-competitor-mode="supply">공급망 영역 ${selected.supply.length}</button><button role="tab" aria-selected="${mode==='excluded'}" data-competitor-mode="excluded">판정 보류 ${selected.excluded.length}</button></div><div class="us-kr-candidates">${items.map(p=>`<article class="us-kr-card"><div class="us-kr-card-heading"><h4><a href="/stock/KR/${esc(p.krTicker)}?tab=company">${esc(p.kr.marketName||p.kr.name)}</a></h4><span class="competitor-badge">${({direct:'직접 경쟁',partial:'부분 경쟁',supply_chain:'공급망 영역 · 계약 미확인',same_industry:'단순 동일 산업',insufficient:'근거 부족'})[p.classification]}</span></div><small>${esc(p.krTicker)} · ${p.score!==null?'근거 충족 점수 '+p.score+'/100':'경쟁 점수 미산출'}</small><p>${esc(p.classification==='supply_chain'?'추출된 제품의 공급망 용도 연결 · 전체 사업의 경쟁 여부와 실제 공급 계약은 미확인':p.reason)}</p>${p.matches.length?`<p><b>${esc(p.matches.map(m=>m.name).join(' · '))}</b></p><small>${esc(p.matches[0].confidence)}</small>`:''}<p class="us-kr-note">공시 ${esc(p.kr.sourceDate)} · 확인 ${esc(stamp(p.kr.lastVerifiedAt||p.kr.checkedAt))} KST</p><p>${number(p.kr.quote?.price)}원 · ${pct(p.kr.quote?.changePct)}<br><small>전일 기준 ${esc(p.kr.quote?.baseDate||'미확인')} · 수집 ${esc(stamp(p.kr.quote?.syncedAt))} KST</small></p><button data-competitor-compare="${esc(p.krTicker)}" aria-expanded="${pairTicker===p.krTicker}">두 기업 제품·근거 비교</button><p class="us-kr-note">과거 다음 한국 거래일 반응: 자료 부족 · 표본 0개<br>기존 산업별 반응을 개별 경쟁사의 통계로 사용하지 않습니다.</p></article>`).join('')||`<p class="us-kr-empty">${mode==='competitors'?'확인된 국내 직접 경쟁사 없음':'확인된 결과 없음'}<br><small>${selected.profileStatus==='ready'?'현재 수집·검증된 프로필 범위의 결과입니다. 전체 국내 기업에 경쟁사가 없다는 뜻은 아닙니다.':'공시 프로필 수집·검증이 끝나지 않아 경쟁 관계를 확정하지 않습니다.'}</small></p>`}</div>${comparison?`<section class="competitor-comparison"><h3>제품별 근거 비교</h3>${comparison.matches.length>1?`<label>비교 제품 <select data-competitor-product>${comparison.matches.map(m=>`<option value="${esc(m.product)}" ${m.product===match.product?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label>`:''}<div class="competitor-columns">${profileColumn(selected.profile,'us',match)}${profileColumn(comparison.kr,'kr',match)}</div><p class="us-kr-note">공시 기준일은 서로 다를 수 있습니다. 매출 비중이 없으면 중요도 점수는 0이며 직접 경쟁으로 승격하지 않습니다.</p></section>`:''}${selected.profile?`<details class="competitor-us-profile"><summary>미국 기업 사업 프로필 · ${selected.profile.products.length}개 제품 추출</summary>${profileColumn(selected.profile,'us',null)}</details>`:''}</section>`:'<p class="us-kr-empty">미국 기업 카드를 누르거나 종목을 검색하면 제품·고객 시장의 경쟁 근거를 비교합니다.</p>'}<footer class="us-kr-note"><p>${(data?.coverage||[]).map(c=>`${c.market==='US'?'미국':'국내'} 프로필 ${c.available||0}개 / 등록 ${c.attempted}개`).join(' · ')}</p><details><summary>분류 기준·데이터 범위</summary><p>제품 중복 ${data?.weights?.product} · 같은 역할 ${data?.weights?.role} · 고객 시장 ${data?.weights?.market} · 제품 매출 중요도 ${data?.weights?.importance} · 최신성 ${data?.weights?.freshness}. 동일 제품·역할·용도·고객 유형·최종 시장은 필수 조건입니다. 매출 비중 미확인 시 직접 경쟁으로 분류하지 않습니다.</p>${(data?.limits||[]).map(t=>`<p>${esc(t)}</p>`).join('')}<p>공시 기반 알고리즘 판정이며 공인 경쟁사 명단이 아닙니다. 고객·공급 계약이나 주가 방향은 추정하지 않습니다.</p></details></footer></div>`;
  root.querySelector('.competitor-search').onsubmit=e=>e.preventDefault();
  root.querySelector('#competitor-query').oninput=e=>{clearTimeout(searchTimer);searchController?.abort();const q=e.target.value.trim();const host=root.querySelector('#competitor-search-results');host.textContent=q?'검색 중…':'';if(!q)return;searchTimer=setTimeout(async()=>{const controller=new AbortController();searchController=controller;try{const d=await(await fetch('/api/competitors?q='+encodeURIComponent(q),{signal:controller.signal})).json();if(controller.signal.aborted)return;host.innerHTML=d.items?.map(c=>`<button type="button" data-competitor-select="${esc(c.ticker)}">${esc(c.ticker)} · ${esc(c.name)}</button>`).join('')||'검색 결과 없음 · 사업 프로필 인덱스 수집 상태를 확인해 주세요.';}catch{if(!controller.signal.aborted)host.textContent='검색 실패';}},220);};
 }
 root.addEventListener('change',e=>{if(e.target.matches('[data-competitor-product]')){productId=e.target.value;render();}});
 root.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.hasAttribute('data-competitor-select'))void select(b.dataset.competitorSelect);else if(b?.hasAttribute('data-competitor-mode')){mode=b.dataset.competitorMode;pairTicker='';render();}else if(b?.hasAttribute('data-competitor-compare')){pairTicker=pairTicker===b.dataset.competitorCompare?'':b.dataset.competitorCompare;render();root.querySelector('.competitor-comparison')?.scrollIntoView({block:'nearest',behavior:'smooth'});}else if(b?.hasAttribute('data-competitor-refresh'))void load();const a=e.target.closest('a[href^="/"]');if(a&&navigate&&!e.ctrlKey&&!e.metaKey){e.preventDefault();navigate(a.getAttribute('href'));}});
 const timer=setInterval(()=>{if(ticker&&data?.selected?.profileStatus==='pending'&&!root.closest('[hidden]')&&!root.querySelector('#competitor-query')?.value)void load();},60000);
 void load();return {refresh:()=>load(),destroy(){clearInterval(timer);clearTimeout(searchTimer);searchController?.abort();}};
}
